/// <summary>
/// When <c>METInventOnHandWarningNotAllowedBlankDimInHierarchyFlight</c> is enabled,
/// a different label (@SCM:WarningNotAllowedBlankDimInHierarchy) is used instead on the InventOnhandItem form when an invalid blank value is detected in displayed inventory dimensions.
/// </summary>
internal final class METInventOnHandWarningNotAllowedBlankDimInHierarchyFlight extends Flight
{
    static private METInventOnHandWarningNotAllowedBlankDimInHierarchyFlight singleton = new METInventOnHandWarningNotAllowedBlankDimInHierarchyFlight();

}

Method.Source:
/// <summary>
/// isEnabledByDefault method is used to determine if the flight is enabled by default.
/// </summary>
/// <returns>boolean</returns>
[Hookable(false)]
protected boolean isEnabledByDefault()
{
    return true;
}

/// <summary>
/// singleton method returns the single instance of the METInventOnHandWarningNotAllowedBlankDimInHierarchyFlight class.
/// </summary>
/// <returns>METInventOnHandWarningNotAllowedBlankDimInHierarchyFlight</returns>
[Hookable(false)]
public static METInventOnHandWarningNotAllowedBlankDimInHierarchyFlight instance()
{
    return singleton;
}
